('9936dad5-44f4-545d-8d54-b01a184b6de4','1e34a758-a0b0-5dc1-9fc4-357d165bcbdb',31,'mcq',$q$Chọn nghĩa đúng của câu: 我们的任务任重道远。$q$,null,null,null,$q$["Nhiệm vụ của chúng ta còn rất nặng nề và xa xôi.", "Đoàn kết là sức mạnh.", "Con sông này chảy không ngừng.", "Anh ấy luôn bác bỏ những quan điểm mới."]$q$::jsonb,1,$q$任重道远$q$,3,null,null),
('7cb797ef-b102-5334-97ed-446e4e9f0cc2','1e34a758-a0b0-5dc1-9fc4-357d165bcbdb',32,'mcq',$q$Chọn nghĩa đúng của câu: 他的良心很清白。$q$,null,null,null,$q$["Lương tâm của anh ấy rất trong sáng.", "Luật pháp được thi hành bắt buộc.", "Cô ấy đã giành được giải á quân.", "Loại bệnh này rất khó để miễn dịch."]$q$::jsonb,1,$q$良心$q$,3,null,null),
('2c5b0069-9bbd-5d6b-9116-729befb72b29','1e34a758-a0b0-5dc1-9fc4-357d165bcbdb',33,'mcq',$q$Chọn nghĩa đúng của câu: 垃圾堆积如山。$q$,null,null,null,$q$["Rác chất đống như núi.", "Chúng tôi đã nghiên cứu cấu trúc địa chất.", "Cách làm này quá tham lợi trước mắt.", "Hành vi của anh ấy không chê vào đâu được."]$q$::jsonb,1,$q$堆积$q$,3,null,null),
('15e5f18c-889a-5826-b0e0-59a8d2fb9079','1e34a758-a0b0-5dc1-9fc4-357d165bcbdb',34,'mcq',$q$Chọn nghĩa đúng của câu: 我们都崇敬他。$q$,null,null,null,$q$["Chính phủ trợ cấp cho nông nghiệp.", "Chúng tôi đều kính trọng anh ấy.", "Anh ấy hoàn thành công việc một cách ổn thỏa.", "Tin tức này đã làm rối loạn trật tự."]$q$::jsonb,1,$q$崇敬$q$,3,null,null),
('cf85c33e-8c6d-5b68-b097-f0d15f6259a1','1e34a758-a0b0-5dc1-9fc4-357d165bcbdb',35,'mcq',$q$Chọn nghĩa đúng của câu: 我们正在跟踪调查。$q$,null,null,null,$q$["Hai mẫu này chồng lên nhau.", "Chú chó ngậm khúc xương.", "Họ quyết định chấm dứt hợp đồng.", "Chúng tôi đang theo dõi điều tra."]$q$::jsonb,1,$q$跟踪$q$,3,null,null),
('98d27eb5-19fe-59d5-b720-5096be12a4d5','1e34a758-a0b0-5dc1-9fc4-357d165bcbdb',36,'mcq',$q$Chọn nghĩa đúng của câu: 公司支出了大量资金。$q$,null,null,null,$q$["Cuộc họp diễn ra rất long trọng.", "Công ty đã chi tiêu một số tiền lớn.", "Vui lòng đánh dấu vị trí trên bản đồ.", "Hành lang của trường rất rộng rãi."]$q$::jsonb,1,$q$支出$q$,3,null,null),
('17617683-5bd7-5a2b-8435-465cef42acd1','1e34a758-a0b0-5dc1-9fc4-357d165bcbdb',37,'mcq',$q$Chọn nghĩa đúng của câu: 他因为堕落而失去了工作。$q$,null,null,null,$q$["Quan điểm của anh ấy quá cực đoan.", "Anh ấy mất việc vì sa ngã.", "Quê quán của tôi là Bắc Kinh.", "Những người nông dân chăm sóc cây ăn quả rất cẩn thận."]$q$::jsonb,1,$q$堕落$q$,3,null,null),
('898bd1ae-3cb2-5828-b6ad-3a5a383996ce','1e34a758-a0b0-5dc1-9fc4-357d165bcbdb',38,'mcq',$q$Chọn nghĩa đúng của câu: 小孩子经常流鼻涕。$q$,null,null,null,$q$["Trẻ con thường hay chảy nước mũi.", "Anh ấy cảm thấy rất bị đè nén.", "Vết sẹo trên mặt anh ấy rất rõ.", "Anh ấy là một đồng chí nhiệt tình."]$q$::jsonb,1,$q$鼻涕$q$,3,null,null),
('09620623-bd68-5e9d-9eb8-8e5153052509','1e34a758-a0b0-5dc1-9fc4-357d165bcbdb',39,'mcq',$q$Chọn nghĩa đúng của câu: 他的话起到了很大的约束作用。$q$,null,null,null,$q$["Họ đang cố gắng xoay chuyển tình thế.", "Mọi thứ vẫn diễn ra như thường lệ.", "Anh ấy là đồ đệ của tôi.", "Lời nói của anh ấy có tác dụng ràng buộc lớn."]$q$::jsonb,1,$q$约束$q$,3,null,null),
('ee768a3b-8716-5c25-9680-aba1ccc17682','1e34a758-a0b0-5dc1-9fc4-357d165bcbdb',40,'mcq',$q$Chọn nghĩa đúng của câu: 这本小说的情节很紧张。$q$,null,null,null,$q$["Những chuyện cũ vẫn còn rõ ràng trong tâm trí.", "Họ sống trong một biệt thự sang trọng.", "Chúng ta cần đi nhanh lên, nếu không sẽ trễ.", "Cốt truyện của cuốn tiểu thuyết này rất căng thẳng."]$q$::jsonb,1,$q$情节$q$,3,null,null),
('78ad3a10-0509-59e1-b135-977d56073940','1e34a758-a0b0-5dc1-9fc4-357d165bcbdb',41,'mcq',$q$Chọn nghĩa đúng của câu: 请更正这个错误。$q$,null,null,null,$q$["Kết quả ngoài dự đoán của chúng tôi.", "Vui lòng sửa lỗi này.", "Anh ấy nhận được sự đền đáp xứng đáng.", "Tầm nhìn của anh ấy rất rộng."]$q$::jsonb,1,$q$更正$q$,3,null,null),
('57215a57-ad0e-537c-bbf2-59e274497afe','1e34a758-a0b0-5dc1-9fc4-357d165bcbdb',42,'mcq',$q$Chọn nghĩa đúng của câu: 他是一个独裁者。$q$,null,null,null,$q$["Trước đây chúng tôi luôn đi du lịch cùng nhau.", "Suy thoái kinh tế ảnh hưởng đến nhiều doanh nghiệp.", "Anh ấy là một kẻ độc tài.", "Cách làm của anh ấy rất cơ hội."]$q$::jsonb,1,$q$独裁$q$,3,null,null),
('1aaf448d-251f-51ce-86ec-7b2480037731','1e34a758-a0b0-5dc1-9fc4-357d165bcbdb',43,'mcq',$q$Chọn nghĩa đúng của câu: 这是一个新玩意儿。$q$,null,null,null,$q$["Anh ấy ưỡn ngực lên.", "Đây là một món đồ chơi mới.", "Cô ấy rất lắm lời, luôn nói không ngừng.", "Anh ta có tham vọng lớn."]$q$::jsonb,1,$q$玩意儿$q$,3,null,null),
('0525f034-32f0-5114-babd-fcb8df240e38','1e34a758-a0b0-5dc1-9fc4-357d165bcbdb',44,'mcq',$q$Chọn nghĩa đúng của câu: 这部电影真是让人看得过瘾。$q$,null,null,null,$q$["Tác phẩm của anh ấy thể hiện cảm xúc phong phú.", "Bộ phim này thực sự khiến người xem đã mắt.", "Chiếc hộp này nặng tới mười cân Anh.", "Tôi sẽ cố gắng đền đáp sự giúp đỡ của bạn."]$q$::jsonb,1,$q$过瘾$q$,3,null,null),
('d61d40a7-f301-5610-b575-fc8865253156','1e34a758-a0b0-5dc1-9fc4-357d165bcbdb',45,'mcq',$q$Chọn nghĩa đúng của câu: 他的行为很古怪。$q$,null,null,null,$q$["Anh ấy là một thám tử nổi tiếng.", "Ý kiến của anh ấy rất có lý, tôi cũng đồng ý.", "Lần này đã thử thách khả năng của anh ấy.", "Hành vi của anh ấy rất kỳ lạ."]$q$::jsonb,1,$q$古怪$q$,3,null,null),
('2111f7c2-e52d-51cf-a1df-94ab1f0fead3','1e34a758-a0b0-5dc1-9fc4-357d165bcbdb',46,'match',$q$Nối mỗi từ với nghĩa tiếng Việt đúng.$q$,null,null,null,$q${"left": ["镶嵌", "监视", "扭转", "尽快"], "right": ["Khảm nạm", "giám sát, theo dõi", "Xoay chuyển, xoay ngược", "nhanh chóng, càng sớm càng tốt"]}$q$::jsonb,1,$q$镶嵌$q$,4,null,null),
