('b9a9c6ad-10ae-51ac-92f2-c083a36ed439','1e34a758-a0b0-5dc1-9fc4-357d165bcbdb',50,'match',$q$Nối mỗi từ với nghĩa tiếng Việt đúng.$q$,null,null,null,$q${"left": ["咋", "顿时", "不言而喻", "反思"], "right": ["Sao (phương ngữ)", "ngay lập tức", "không cần nói cũng hiểu", "suy nghĩ lại, ngẫm lại"]}$q$::jsonb,1,$q$咋$q$,4,null,null),
('4c6629c3-ead9-54c5-9b23-0ea690621bb5','6a48a8e4-b68a-5bb1-9ab6-18a78dec9ae9',1,'essay',$q$Đọc đoạn văn dưới đây rồi viết bản tóm tắt khoảng 100 chữ Hán bằng lời của bạn. (Đề thật yêu cầu đọc khoảng 1000 chữ và viết khoảng 400 chữ; đây là đoạn mẫu rút gọn.)$q$,$q$在现代社会，越来越多的人习惯于用手机阅读新闻、观看视频、与朋友交流。手机给我们的生活带来了极大的方便：我们可以随时查找资料，也可以不出家门就完成购物和付款。然而，长时间使用手机也带来了不少问题。首先，许多人每天盯着屏幕，视力明显下降；其次，人们面对面交流的时间越来越少，家人之间、朋友之间的感情有时反而变得疏远；再次，大量零碎的信息让人难以集中注意力，学习和工作的效率受到影响。
insert into exam_answer_keys(question_id,answer,explanation) values
('71a086d4-30fc-51ce-9a10-f02b7034b681',$q$"天气冷得以致无法出门。"$q$::jsonb,$q$以致 (yǐzhì): Kết quả là. Ví dụ: 天气冷得以致无法出门。 — Trời lạnh đến mức không thể ra ngoài.$q$),
('6d60ec61-d75e-5434-b412-9de5b6276cfc',$q$"这家公司规模庞大。"$q$::jsonb,$q$庞大 (pángdà): To lớn, khổng lồ. Ví dụ: 这家公司规模庞大。 — Công ty này có quy mô rất lớn.$q$),
('3edd5f27-127d-5f22-8c95-6027dfa6fef8',$q$"他吃了不干净的食物后呕吐了。"$q$::jsonb,$q$呕吐 (ǒutù): Nôn mửa. Ví dụ: 他吃了不干净的食物后呕吐了。 — Anh ấy nôn mửa sau khi ăn thức ăn không sạch.$q$),
('25b57da4-8770-52eb-9b13-76565597b3ec',$q$"婴儿在健康地发育。"$q$::jsonb,$q$发育 (fā yù): phát triển, trưởng thành. Ví dụ: 婴儿在健康地发育。 — Em bé đang phát triển khỏe mạnh.$q$),
('05c7141f-c4d3-5301-abd7-39002fbc1f32',$q$"他的行为很文雅。"$q$::jsonb,$q$文雅 (wényǎ): Văn nhã. Ví dụ: 他的行为很文雅。 — Hành động của anh ấy rất nhã nhặn.$q$),
('7fb740b7-eb88-5da8-b731-d8d241be5493',$q$"他经历了许多周折才成功。"$q$::jsonb,$q$周折 (zhōuzhé): Trắc trở. Ví dụ: 他经历了许多周折才成功。 — Anh ấy đã trải qua nhiều khó khăn mới thành công.$q$),
('e5858b91-4749-5bd7-9822-4153c0466d0f',$q$"tranh thủ thời gian"$q$::jsonb,$q$抽空 (chōu kòng): tranh thủ thời gian. Ví dụ: 我会抽空来看你。 — Tôi sẽ tranh thủ thời gian để đến thăm bạn.$q$),
('19335f0a-9180-5deb-8d26-88bfba6eac67',$q$"yên tĩnh, tĩnh mịch"$q$::jsonb,$q$寂静 (jì jìng): yên tĩnh, tĩnh mịch. Ví dụ: 夜晚的森林非常寂静。 — Khu rừng vào ban đêm rất yên tĩnh.$q$),
('59cc15c9-5cc6-58aa-b814-a8fbb51d6e8d',$q$"tiền đồ sáng lạn"$q$::jsonb,$q$锦绣前程 (jǐn xiù qián chéng): tiền đồ sáng lạn. Ví dụ: 你有一段锦绣前程。 — Bạn có một tương lai tươi sáng.$q$),
