('021f056c-cb8e-56c6-a04a-cfc4e1bf108f',$q$"就业"$q$::jsonb,$q$就业 (jiù yè): việc làm, tìm việc. Ví dụ: 他最近找到了就业机会。 — Gần đây anh ấy tìm được cơ hội việc làm.$q$),
('f066be71-db80-5196-bf12-231cc995abbd',$q$"流通"$q$::jsonb,$q$流通 (liútōng): Lưu thông. Ví dụ: 货物需要流通才能销售。 — Hàng hóa cần lưu thông mới có thể bán được.$q$),
('97904181-cdfb-5e49-929a-b9ec0a8bad59',$q$"苍白"$q$::jsonb,$q$苍白 (cāng bái): xanh xao, tái nhợt. Ví dụ: 他的脸色很苍白。 — Sắc mặt của anh ấy rất nhợt nhạt.$q$),
('4bb84561-d489-5479-b1ac-e904eb1a0dc1',$q$"举足轻重"$q$::jsonb,$q$举足轻重 (jǔ zú qīng zhòng): có vai trò quan trọng. Ví dụ: 他在团队中举足轻重。 — Anh ấy là người quan trọng trong đội.$q$),
('b428b13a-358a-5aaa-846b-5580b098c744',$q$"危机"$q$::jsonb,$q$危机 (wēijī): Khủng hoảng. Ví dụ: 公司正面临财务危机。 — Công ty đang đối mặt với khủng hoảng tài chính.$q$),
('da716983-79cb-5c8b-b402-c24d22ed417b',$q$"正规"$q$::jsonb,$q$正规 (zhèngguī): Quy cách. Ví dụ: 我们需要正规化管理。 — Chúng ta cần quản lý hợp lý.$q$),
('334e1473-b2d2-5ae1-9231-28547209d2e4',$q$"世代"$q$::jsonb,$q$世代 (shìdài): Thế hệ. Ví dụ: 这个传统世代相传。 — Truyền thống này được truyền từ thế hệ này sang thế hệ khác.$q$),
('6c6645d8-80f0-5130-8543-06a2de1b721c',$q$"Những sản phẩm này vừa tốt vừa rẻ."$q$::jsonb,$q$物美价廉 (wùměi jiàlián): Hàng tốt giá rẻ. Ví dụ: 这些商品物美价廉。 — Những sản phẩm này vừa tốt vừa rẻ.$q$)
insert into exam_answer_keys(question_id,answer,explanation) values
('9936dad5-44f4-545d-8d54-b01a184b6de4',$q$"Nhiệm vụ của chúng ta còn rất nặng nề và xa xôi."$q$::jsonb,$q$任重道远 (rènzhòngdàoyuǎn): Trách nhiệm nặng nề và đường dài. Ví dụ: 我们的任务任重道远。 — Nhiệm vụ của chúng ta còn rất nặng nề và xa xôi.$q$),
('7cb797ef-b102-5334-97ed-446e4e9f0cc2',$q$"Lương tâm của anh ấy rất trong sáng."$q$::jsonb,$q$良心 (liángxīn): Lương tâm. Ví dụ: 他的良心很清白。 — Lương tâm của anh ấy rất trong sáng.$q$),
('2c5b0069-9bbd-5d6b-9116-729befb72b29',$q$"Rác chất đống như núi."$q$::jsonb,$q$堆积 (duī jī): chất đống, tích lũy. Ví dụ: 垃圾堆积如山。 — Rác chất đống như núi.$q$),
('15e5f18c-889a-5826-b0e0-59a8d2fb9079',$q$"Chúng tôi đều kính trọng anh ấy."$q$::jsonb,$q$崇敬 (chóng jìng): kính trọng, tôn kính. Ví dụ: 我们都崇敬他。 — Chúng tôi đều kính trọng anh ấy.$q$),
('cf85c33e-8c6d-5b68-b097-f0d15f6259a1',$q$"Chúng tôi đang theo dõi điều tra."$q$::jsonb,$q$跟踪 (gēn zōng): theo dõi, bám đuôi. Ví dụ: 我们正在跟踪调查。 — Chúng tôi đang theo dõi điều tra.$q$),
('98d27eb5-19fe-59d5-b720-5096be12a4d5',$q$"Công ty đã chi tiêu một số tiền lớn."$q$::jsonb,$q$支出 (zhīchū): Chi tiêu. Ví dụ: 公司支出了大量资金。 — Công ty đã chi tiêu một số tiền lớn.$q$),
('17617683-5bd7-5a2b-8435-465cef42acd1',$q$"Anh ấy mất việc vì sa ngã."$q$::jsonb,$q$堕落 (duò luò): sa đọa, đồi bại. Ví dụ: 他因为堕落而失去了工作。 — Anh ấy mất việc vì sa ngã.$q$),
('898bd1ae-3cb2-5828-b6ad-3a5a383996ce',$q$"Trẻ con thường hay chảy nước mũi."$q$::jsonb,$q$鼻涕 (bí tì): nước mũi. Ví dụ: 小孩子经常流鼻涕。 — Trẻ con thường hay chảy nước mũi.$q$),
('09620623-bd68-5e9d-9eb8-8e5153052509',$q$"Lời nói của anh ấy có tác dụng ràng buộc lớn."$q$::jsonb,$q$约束 (yuēshù): Ràng buộc. Ví dụ: 他的话起到了很大的约束作用。 — Lời nói của anh ấy có tác dụng ràng buộc lớn.$q$),
('ee768a3b-8716-5c25-9680-aba1ccc17682',$q$"Cốt truyện của cuốn tiểu thuyết này rất căng thẳng."$q$::jsonb,$q$情节 (qíngjié): Tình tiết, chi tiết. Ví dụ: 这本小说的情节很紧张。 — Cốt truyện của cuốn tiểu thuyết này rất căng thẳng.$q$),
('78ad3a10-0509-59e1-b135-977d56073940',$q$"Vui lòng sửa lỗi này."$q$::jsonb,$q$更正 (gēng zhèng): cải chính, sửa lại. Ví dụ: 请更正这个错误。 — Vui lòng sửa lỗi này.$q$),
('57215a57-ad0e-537c-bbf2-59e274497afe',$q$"Anh ấy là một kẻ độc tài."$q$::jsonb,$q$独裁 (dú cái): độc tài. Ví dụ: 他是一个独裁者。 — Anh ấy là một kẻ độc tài.$q$),
('1aaf448d-251f-51ce-86ec-7b2480037731',$q$"Đây là một món đồ chơi mới."$q$::jsonb,$q$玩意儿 (wányìr): Đồ chơi, món đồ. Ví dụ: 这是一个新玩意儿。 — Đây là một món đồ chơi mới.$q$),
('0525f034-32f0-5114-babd-fcb8df240e38',$q$"Bộ phim này thực sự khiến người xem đã mắt."$q$::jsonb,$q$过瘾 (guò yǐn): đã, sướng, thoả thích. Ví dụ: 这部电影真是让人看得过瘾。 — Bộ phim này thực sự khiến người xem đã mắt.$q$),
('d61d40a7-f301-5610-b575-fc8865253156',$q$"Hành vi của anh ấy rất kỳ lạ."$q$::jsonb,$q$古怪 (gǔ guài): kỳ quái, kỳ lạ. Ví dụ: 他的行为很古怪。 — Hành vi của anh ấy rất kỳ lạ.$q$),
