('81da8f17-ff21-5898-b640-935fcc452eb2',$q${"实力": "Thực lực", "啰唆": "Lắm lời, lằng nhằng", "竞选": "tranh cử, vận động bầu cử", "时机": "Thời cơ, cơ hội"}$q$::jsonb,$q$实力 = Thực lực; 啰唆 = Lắm lời, lằng nhằng; 竞选 = tranh cử, vận động bầu cử; 时机 = Thời cơ, cơ hội$q$),
