('f64741af-1f3c-5544-8dcd-7ec240e1e944','16571a47-3671-5c0e-b9ca-78b9033ff18b',45,'mcq',$q$Chọn nghĩa đúng của câu: 他用子弹击中了目标。$q$,null,null,null,$q$["Chúng ta phải phong tỏa biên giới.", "Anh ta chiến đấu dũng cảm trên chiến trường.", "Anh ấy bắn trúng mục tiêu bằng đạn.", "Họ bị phát hiện câu kết với kẻ thù."]$q$::jsonb,1,$q$子弹$q$,3,null,null),
